        return false;
    }
    int strLen = str.length();
    int suffLen = suffix.length();
    if (suffLen > strLen) {
        return false;
    }
    int start = strLen - suffLen;
    if (ignoreCase) {
        for (int i = 0; i < suffLen; i++) {
            char c1 = Character.toLowerCase(str.charAt(start + i));
            char c2 = Character.toLowerCase(suffix.charAt(i));
            if (c1 != c2) {
                return false;
            }
        }
        return true;
    } else {
        return str.regionMatches(start, suffix, 0, suffLen);
    }
}

