private void enlarge(final int size) {
    if (size <= 0) {
        return;
    }
    int currentLen = this.length; // number of bytes currently stored
    int currentCapacity = this.data.length; // current backing array capacity
    int required = currentLen + size;
    if (required <= currentCapacity) {
        return; // already enough space
    }
    int newCapacity = Math.max(currentCapacity << 1, required);
    byte[] newData = new byte[newCapacity];
    System.arraycopy(this.data, 0, newData, 0, currentLen);
    this.data = newData;
}

